import {cartFeedback} from './motion.js?v=motion-3';
import {products} from './products.js?v=catalog-2';
const $=s=>document.querySelector(s);let lang=localStorage.getItem('bridge-lang')==='ko'?'ko':'zh';
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let cart=read('bridge-cart',{}),favorites=read('bridge-favorites',[]);let query='',category='ALL',filter='all',sort='popular';let visibleLimit=24;
// Only item quantities are retained; delivery details never enter browser storage.
cart=Object.fromEntries(products.filter(p=>Number.isInteger(cart[p.id])&&cart[p.id]>0).map(p=>[p.id,Math.min(p.requestLimit,cart[p.id])]).filter(([,q])=>q>0));
const tr=(zh,ko)=>lang==='zh'?zh:ko;const name=p=>p?.[lang]||p?.en||p?.id||'';const money=(n,currency=lang==='zh'?'CNY':'KRW')=>n==null?tr('待核实','확인 예정'):new Intl.NumberFormat(lang==='zh'?'zh-CN':'ko-KR',{style:'currency',currency,minimumFractionDigits:currency==='USD'?2:0,maximumFractionDigits:currency==='USD'?2:0}).format(n);const price=p=>lang==='zh'?p.cny:p.krw;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'⌂',shop:'▦',orders:'▤',about:'◎',cart:'♧'};let apiAvailable=false;
fetch('./api/health').then(r=>r.ok?r.json():null).then(d=>{apiAvailable=d?.orders===true}).catch(()=>{}).finally(updateServiceStatus);
function updateServiceStatus(){const form=$('#orderForm');if(!form)return;const button=form.querySelector('button[type=submit]');const missing=products.some(p=>cart[p.id]&&!canOrder(p));button.disabled=!apiAvailable||missing;if(missing){$('#submitError').textContent=tr('购物车有当前地区报价未确认的商品，请移除后再申请。','지역 가격 미확인 상품을 장바구니에서 삭제해 주세요.');return}if(!apiAvailable){$('#submitError').textContent=tr('当前为静态展示站，尚未连接申请后台，暂不接收购买申请。请使用本地服务预览申请流程。','현재 정적 데모 사이트로 신청 서버가 연결되지 않았습니다. 신청 기능은 로컬 서버에서 확인해 주세요.')}}
document.addEventListener('click',()=>queueMicrotask(updateServiceStatus));
document.addEventListener('submit',e=>{if(e.target.id==='orderForm'&&(!apiAvailable||products.some(p=>cart[p.id]&&!canOrder(p)))){e.preventDefault();e.stopImmediatePropagation();updateServiceStatus()}},true);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),2600)}
function persist(){localStorage.setItem('bridge-cart',JSON.stringify(cart));$('#cartCount').textContent=Object.values(cart).reduce((a,b)=>a+b,0)}
function route(){return location.hash.slice(1)||'home'}
function chrome(){document.documentElement.lang=lang==='zh'?'zh-CN':'ko';document.title=tr('LEGO Bridge · 连接热爱，跨越国界','LEGO Bridge · 국경을 넘어 이어지는 취미');$('#announcement').textContent=tr('连接中韩收藏市场 · 全球好物，让热爱不止于国界','중국과 한국의 컬렉터를 연결합니다 · 국경을 넘는 즐거움');const links=[['home',tr('首页','홈')],['shop',tr('商品商城','스토어')],['orders',tr('我的申请','구매 신청')],['about',tr('关于我们','소개')]];$('#nav').innerHTML=links.map(([r,n])=>`<a href="#${r}" class="${route().split('/')[0]===r?'active':''}">${n}</a>`).join('');$('#mobileNav').innerHTML=[...links.slice(0,2),['cart',tr('购物车','장바구니')],links[2]].map(([r,n])=>`<a href="#${r}" class="${route()===r?'active':''}"><span>${icons[r]}</span>${n}</a>`).join('');$('#language').textContent=lang==='zh'?'한국어':'中文';$('#cartText').textContent=tr('购物车','장바구니');$('#footer').innerHTML=`<div><a class="footer-brand" href="#home" aria-label="LEGO Bridge Home"><svg class="brand-logo" viewBox="190 260 1610 270" role="img" aria-label="LEGO Bridge"><title>LEGO Bridge</title><image href="./assets/lego-bridge-logo-a.png" width="1983" height="793" /></svg></a><br>${tr('连接全球乐高收藏市场，让限量收藏更简单。','전 세계 LEGO 수집 시장을 연결합니다.')}</div><div>${tr('官方资料查询：2026-10-14 · 平台售价按商家规则计算 · 库存待确认','공식 정보 조회: 2026-10-14 · 판매자 규칙에 따른 가격 · 재고 별도 확인')}<br>${tr('独立收藏服务项目，与 LEGO 集团无隶属关系。LEGO 为其权利人的商标。','LEGO 그룹과 제휴하지 않은 독립 프로젝트입니다. LEGO 상표는 해당 권리자 소유입니다.')}<br><a href="#contact">${tr('联系我们','문의')}</a> · <a href="#privacy">${tr('隐私说明','개인정보 안내')}</a> · <a href="#admin">${tr('管理入口','관리자')}</a></div>`;persist()}
const oldTag=p=>lang==='zh'?p.tag:({'精选收藏':'추천 컬렉션','人气之选':'인기 상품','跨境好价':'추천 가격','收藏推荐':'컬렉터 추천','入门推荐':'입문 추천','建筑美学':'건축 컬렉션'}[p.tag]||'추천');
function img(p,extra=''){return '<img src="'+esc(imageUrl(p.image,480))+'" alt="'+esc(name(p))+'" loading="lazy" '+extra+'>';}

const seriesName=p=>lang==='zh'?(p.seriesZh||p.series):(p.seriesKo||p.series);
const availabilityLabel=s=>s==='E_AVAILABLE'?tr('可购买','구매 가능'):s?.includes('BACKORDER')?tr('可订购，需等待','백오더'):s?.includes('PRE_ORDER')?tr('预售','예약 판매'):s?.includes('OUT_OF_STOCK')||s?.includes('SOLD_OUT')?tr('缺货','품절'):s?.includes('RETIRED')?tr('已停售','판매 종료'):tr('待核实','확인 예정');
const canOrder=p=>p.availableToBuy&&Number.isFinite(price(p))&&price(p)>0;
const tag=p=>p.confirmed?(p.availableToBuy?tr('官网在售','공식 판매 중'):tr('官网暂缺货','공식 일시 품절')):tr('目录待核实','판매 확인 예정');
const seriesList=()=>[...new Map(products.map(p=>[p.series,p])).values()];
const priceRule=()=>tr('中国售价 = 美国官网原价 × 9 × 60%；韩国售价 = 韩国官网售价 × 75%，四舍五入取整数。美国价格保留美元原价。','중국 가격 = 미국 공식 정가 × 9 × 60%, 한국 가격 = 한국 공식 판매가 × 75% (반올림). 미국 가격은 USD 정가입니다.');
function imageUrl(url,width=800){return url+'?fit=bounds&format=jpg&quality=85&width='+width+'&height='+width;}

function card(p){return `<article class="product"><div class="product-image"><span class="badge">${tag(p)}</span><button type="button" class="heart ${favorites.includes(p.id)?'selected':''}" data-favorite="${p.id}" aria-label="${tr('收藏','찜')}" aria-pressed="${favorites.includes(p.id)}"><span class="heart-icon" aria-hidden="true">${favorites.includes(p.id)?'♥':'♡'}</span></button><a href="#product/${p.id}">${img(p)}</a></div><div class="product-info"><div class="meta">${esc(seriesName(p))} · #${p.id} · ${p.pieces.toLocaleString()} ${tr('片','피스')}</div><a href="#product/${p.id}"><h3>${esc(name(p))}</h3></a><div class="price">${money(price(p))}<small>${tr('平台定价','플랫폼 가격')}</small></div><div class="comparison"><span>${tr('美国官网原价','미국 공식 정가')} ${money(p.global,'USD')}</span></div><div class="product-bottom"><span>${tr('库存待确认','재고 확인 필요')}</span><button class="add" data-add="${p.id}" aria-label="${tr('加入购物车','장바구니 담기')} ${esc(name(p))}" ${canOrder(p)?'':'disabled'}>＋</button></div></div></article>`;}
function benefits(){return `<div class="benefits">${[['⇄',tr('三地价格，一目了然','세 지역의 가격 비교'),tr('中国、韩国与国际市场参考，收藏前多一份了解。','중국·한국·미국의 가격 기준을 확인하세요.')],['▣',tr('跨境购买，专人确认','구매 전 개별 확인'),tr('先提交申请，再确认商品、运费和配送安排。','신청 후 상품, 배송비, 배송 일정을 확인합니다.')],['♡',tr('为收藏而连接','수집가를 위한 연결'),tr('从经典套装到设计师作品，连接每一份热爱。','클래식부터 디자이너 작품까지, 취미를 연결합니다.')]].map(([i,h,p])=>`<div class="benefit"><span>${i}</span><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}</div>`}
function searchBox(){return `<form class="search" id="searchForm"><span style="color:#aaa;padding-top:9px">⌕</span><input id="searchInput" type="search" value="${esc(query)}" placeholder="${tr('搜索商品名称、系列或产品编号','상품명, 시리즈 또는 제품 번호 검색')}" aria-label="${tr('搜索商品','상품 검색')}"><button>${tr('搜索','검색')}</button></form>`}
function home(){const list=products.filter(p=>p.confirmed),p=list[0];$('#app').innerHTML=`<section class="hero"><div><span class="pill"><i></i>${tr('中韩乐高收藏 · 官方资料精选','중국·한국 LEGO 컬렉션')}</span><h1>${tr('让收藏，<br><em>跨越国界。</em>','국경을 넘어,<br><em>수집의 즐거움.</em>')}</h1><p>${tr('探索超过 800 片的乐高套装。按系列发现收藏，查看官方价格与平台定价。','800피스가 넘는 LEGO 세트를 시리즈별로 찾아보고 공식 가격과 플랫폼 가격을 확인하세요.')}</p><a href="#shop" class="primary">${tr('探索收藏','컬렉션 둘러보기')} ↗</a></div><div class="hero-art">${img(p,'fetchpriority="high"')}<div class="hero-note">${esc(name(p))}<b>#${p.id} <span style="font-size:9px;color:#888">${p.pieces.toLocaleString()} ${tr('片','피스')}</span></b></div></div></section>${searchBox()}<div class="categories">${seriesList().filter(x=>x.confirmed).slice(0,12).map(x=>`<button class="category" data-category="${esc(x.series)}">${img(x)}<span>${esc(seriesName(x))}</span></button>`).join('')}</div><div class="notice"><span>${list.length} ${tr('款在售套装（含暂缺货） · 800 片以上 · 按系列分类','공식 판매 세트 · 800피스 초과 · 시리즈별 분류')}</span><a href="#shop">${tr('全部系列','전체 시리즈')} →</a></div><div class="section-heading"><div><h2>${tr('精选收藏','추천 컬렉션')} <span style="color:var(--red)">.</span></h2><p>${tr('官方商品资料 · 地区价格 · 更多搭建细节','공식 상품 정보 · 지역 가격 · 디테일')}</p></div><a href="#shop">${tr('查看全部商品','전체 상품 보기')} →</a></div><div class="filters"><button class="filter active" data-home-filter="all">${tr('全部精选','전체 추천')}</button><button class="filter" data-home-filter="stock">${tr('已确认价格','가격 확인')}</button><button class="filter" data-home-filter="affordable">${tr('入门收藏','입문 컬렉션')}</button></div><div class="grid" id="homeGrid">${list.slice(0,8).map(card).join('')}</div>${benefits()}`;}
function selectedProducts(){let list=products.filter(p=>(filter==='pending'?!p.confirmed:filter==='favorites'?true:p.confirmed)&&(category==='ALL'||p.series===category)&&(!query||[p.zh,p.ko,p.en,p.id,p.series,p.seriesZh,p.seriesKo].join(' ').toLowerCase().includes(query.toLowerCase()))&&(filter!=='priced'||canOrder(p))&&(filter!=='favorites'||favorites.includes(p.id)));if(sort==='low')list.sort((a,b)=>(price(a)??Infinity)-(price(b)??Infinity));if(sort==='high')list.sort((a,b)=>(price(b)??-Infinity)-(price(a)??-Infinity));if(sort==='pieces')list.sort((a,b)=>b.pieces-a.pieces);return list;}
function shop(){const list=selectedProducts();$('#app').innerHTML=`<div class="banner-title"><span class="eyebrow">THE COLLECTOR'S EDIT</span><h1>${tr('找到下一份心动。','다음 컬렉션을 발견하세요.')}</h1><p class="muted">${tr('超过 800 片的官方套装资料，按系列探索。','800피스가 넘는 공식 세트를 시리즈별로 살펴보세요.')}</p></div>${searchBox()}<div class="catalog-toolbar"><label>${tr('商品系列','시리즈')}<select id="seriesSelect"><option value="ALL">${tr('全部系列','전체 시리즈')}</option>${seriesList().map(p=>`<option value="${esc(p.series)}" ${category===p.series?'selected':''}>${esc(seriesName(p))} (${products.filter(x=>x.series===p.series).length})</option>`).join('')}</select></label><label>${tr('排序','정렬')}<select id="sort">${[['popular',tr('默认排序','기본순')],['low',tr('价格从低到高','낮은 가격순')],['high',tr('价格从高到低','높은 가격순')],['pieces',tr('颗粒数从多到少','피스 많은순')]].map(([v,n])=>`<option value="${v}" ${sort===v?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="filters">${[['all',tr('官网在售','공식 판매 중')],['priced',tr('已确认价格','가격 확인')],['favorites',tr('我的收藏','찜한 상품')],['pending',tr('中国目录 · 待核实','중국 목록 · 확인 예정')]].map(([v,n])=>`<button class="filter ${filter===v?'active':''}" data-filter="${v}">${n}</button>`).join('')}</div><p class="muted">${list.length} ${tr('款商品 · 数据查询日期：2026-10-14 · 本平台库存需另行确认','개 상품 · 조회일: 2026-10-14 · 플랫폼 재고는 별도 확인')}</p><details class="pricing-note"><summary>${tr('查看地区定价规则与数据说明','지역 가격 규칙 및 출처 안내')}</summary><p>${priceRule()}</p><p>${tr('人民币基准按美元原价乘 9 计算，不是中国官方发售价，也不是实时汇率。仅中国目录出现的商品未确认在售，单独展示；缺少官方价格时标为待核实。','위안화 기준은 USD 정가의 9배이며 중국 공식 출시 가격이나 실시간 환율이 아닙니다. 중국 목록에만 있는 상품은 판매 확인 전 별도 표시하며 미확인 가격은 비워 둡니다.')}</p></details><div class="grid">${list.slice(0,visibleLimit).map(card).join('')}</div>${list.length>visibleLimit?`<div class="load-more"><button class="secondary" id="loadMore">${tr('加载更多商品','더 보기')} (${Math.min(visibleLimit,list.length)} / ${list.length})</button></div>`:''}${list.length?'':`<div class="empty"><h2>${tr('没有找到匹配商品','검색 결과가 없습니다')}</h2><button class="secondary" id="resetFilters">${tr('清除筛选','필터 초기화')}</button></div>`}`;}
function detail(id){const p=products.find(p=>p.id===id);if(!p){$('#app').innerHTML=`<div class="empty">${tr('商品不存在或不在当前目录中','현재 목록에 없는 상품입니다')} <a href="#shop">← ${tr('返回商城','스토어')}</a></div>`;return}const urls=p.images;$('#app').innerHTML=`<div class="breadcrumb"><a href="#home">${tr('首页','홈')}</a> / <a href="#shop">${tr('商品商城','스토어')}</a> / #${p.id}</div><div class="detail-top"><div class="detail-gallery"><div class="detail-photo"><img id="galleryImage" src="${esc(imageUrl(urls[0]))}" alt="${esc(name(p))} · ${tr('主图','대표 이미지')}"></div><div class="gallery-thumbs">${urls.map((url,i)=>`<button type="button" class="${i===0?'active':''}" data-gallery="${i}" data-product-id="${p.id}" aria-label="${tr('查看','보기')} ${i===0?tr('主图','대표 이미지'):tr('细节图','디테일')+' '+i}" aria-pressed="${i===0}"><img src="${esc(imageUrl(url,160))}" alt=""><span>${i===0?tr('主图','대표'):tr('细节','디테일')+' '+i}</span></button>`).join('')}</div>${urls.length<3?`<p class="consent-note">${tr('部分细节图待核实，未用其他商品图片替代。','일부 디테일 이미지는 확인 중이며 다른 상품 이미지를 사용하지 않습니다.')}</p>`:''}${p.detailSource==='OFFICIAL_IMAGE_SCREENSHOT_CROP'?'<p class="consent-note">'+tr('细节图为本套装官方主图的局部截图。','디테일 이미지는 이 세트의 공식 이미지 부분 캡처입니다.')+'</p>':''}</div><div class="detail-panel"><span class="eyebrow">${esc(seriesName(p))} · #${p.id}</span><h1>${esc(name(p))}</h1><p class="muted">${tag(p)} · ${tr('官方资料查询日期','공식 정보 조회일')} ${p.updated}</p><div class="price">${money(price(p))}<small>${tr('平台定价','플랫폼 가격')}</small></div><p class="muted">${lang==='zh'?tr('按美国官方原价 × 9 × 60% 取整数',''):tr('','한국 공식 판매가의 75%, 반올림')}</p><div class="specs"><div><span>${tr('产品编号','제품 번호')}</span>#${p.id}</div><div><span>${tr('颗粒数','피스 수')}</span>${p.pieces.toLocaleString()}</div><div><span>${tr('建议年龄','권장 연령')}</span>${esc(p.age||tr('待核实','확인 예정'))}</div><div><span>${tr('本平台库存','플랫폼 재고')}</span>${tr('待采购确认','구매 확인 필요')}</div></div><div class="detail-actions"><button class="primary" data-add="${p.id}" ${canOrder(p)?'':'disabled'}>${tr('加入购物车','장바구니 담기')} ＋</button><button class="secondary" data-buy="${p.id}" ${canOrder(p)?'':'disabled'}>${tr('申请购买','구매 신청')}</button><a class="secondary" href="#contact">${tr('咨询','문의')}</a></div><p class="consent-note">${tr('官网可购买状态不代表本平台有现货。库存、商品状态、最终报价、运费和税费需确认；此处不收款。','공식 판매 상태는 플랫폼 재고를 의미하지 않습니다. 재고·제품 상태·최종 견적·배송비·세금은 별도 확인하며 온라인 결제는 제공하지 않습니다.')}</p></div></div><section class="panel"><div class="section-heading" style="margin-top:0"><div><h2>🌍 ${tr('地区价格与平台定价','지역 가격과 플랫폼 가격')}</h2><p>${tr('各地区保留本币，避免混用汇率','지역별 통화 그대로 표시')}</p></div></div><div class="table-scroll"><table><thead><tr><th>${tr('地区','지역')}</th><th>${tr('定价依据','가격 기준')}</th><th>${tr('平台售价 / 参考价','플랫폼 / 참고 가격')}</th></tr></thead><tbody><tr><td>${tr('中国','중국')} · CNY</td><td>${money(p.china,'CNY')}<br><small>${tr('美国原价 × 9 的定价基准','미국 정가 × 9 기준')}</small></td><td>${money(p.cny,'CNY')}<br><small>${tr('基准的六折','기준의 60%')}</small></td></tr><tr><td>${tr('韩国','한국')} · KRW</td><td>${money(p.korea,'KRW')}<br><small>${tr('韩国官网售价','한국 공식 판매가')}</small></td><td>${money(p.krw,'KRW')}<br><small>${tr('官网售价的 75%','공식 판매가의 75%')}</small></td></tr><tr><td>${tr('美国 / 国际参考','미국 / 국제 참고')} · USD</td><td>${money(p.global,'USD')}<br><small>${tr('美国官网原价','미국 공식 정가')}</small></td><td>${money(p.global,'USD')}<br><small>${tr('保留原价','정가 유지')}</small></td></tr></tbody></table></div><p class="consent-note">${priceRule()} ${tr('中国基准不是核实的官方发售价，美元乘 9 是商家定价规则，不是实时汇率。价格不含另行确认的运费、税费及服务费。','중국 기준은 확인된 공식 출시가가 아니며 USD × 9는 판매자 규칙으로 실시간 환율이 아닙니다. 배송비·세금·서비스 수수료는 별도입니다.')}</p><div class="source-links">${[['cn',tr('中国官网资料','중국 공식 정보')],['kr',tr('韩国官网价格','한국 공식 가격')],['us',tr('美国官网原价','미국 공식 정가')]].filter(([k])=>p.sources[k]).map(([k,n])=>`<a href="${esc(p.sources[k])}" target="_blank" rel="noopener">${n} ↗</a>`).join('')}</div><p class="consent-note">${tr('美国官网状态：','미국 공식 상태: ')}${availabilityLabel(p.availability.us)} · ${tr('韩国官网状态：','한국 공식 상태: ')}${availabilityLabel(p.availability.kr)}</p><p class="consent-note">${tr('查询日期：','조회일: ')}${p.updated} · ${tr('价格与在售状态为查询时的快照，不是实时同步。','가격·판매 상태는 조회 시점의 정보로 실시간 동기화가 아닙니다.')}</p></section>`;}
function cartPage(){const items=products.filter(p=>cart[p.id]);if(!items.length){$('#app').innerHTML=`<div class="empty"><div style="font-size:45px">♧</div><h2>${tr('下一份收藏，正在等你。','다음 컬렉션이 기다리고 있어요.')}</h2><p>${tr('购物车还是空的，先去发现喜欢的套装吧。','마음에 드는 세트를 장바구니에 담아 보세요.')}</p><a href="#shop" class="primary">${tr('探索商品','상품 둘러보기')} →</a></div>`;return}const total=items.some(p=>price(p)==null)?null:items.reduce((s,p)=>s+price(p)*cart[p.id],0);$('#app').innerHTML=`<div class="banner-title"><span class="eyebrow">YOUR NEXT COLLECTION</span><h1>${tr('购物车','장바구니')}</h1><p class="muted">${tr('先申请，后确认。把跨境收藏的细节交给我们。','먼저 신청하고, 재고와 배송 조건을 확인하세요.')}</p></div><div class="cart-layout"><section class="panel" style="margin-top:0">${items.map(p=>`<div class="cart-row">${img(p)}<div><div class="meta">#${p.id}</div><h3><a href="#product/${p.id}">${esc(name(p))}</a></h3><div class="price">${money(price(p))}</div><button class="remove" data-remove="${p.id}">${tr('移除','삭제')}</button></div><div class="quantity"><button data-quantity="${p.id}" data-delta="-1" aria-label="${tr('减少数量','수량 감소')}">−</button><span>${cart[p.id]}</span><button data-quantity="${p.id}" data-delta="1" ${cart[p.id]>=p.requestLimit?'disabled':''} aria-label="${tr('增加数量','수량 증가')}">＋</button></div></div>`).join('')}</section><section class="panel" style="margin-top:0"><h2>${tr('购买申请','구매 신청')}</h2><div class="summary-line"><span>${tr('商品小计','상품 소계')}</span><strong>${money(total)}</strong></div><div class="summary-line muted"><span>${tr('跨境运费 / 税费','국제 배송비 / 세금')}</span><span>${tr('待确认','확인 예정')}</span></div><hr style="border:0;border-top:1px solid #eee;margin:20px 0"><form class="form" id="orderForm"><label>${tr('姓名','이름')}<input name="customer" autocomplete="name" maxlength="80" required></label><label>${tr('联系邮箱','이메일')}<input name="email" type="email" autocomplete="email" maxlength="160" required></label><label>${tr('联系电话（选填）','연락처 (선택)')}<input name="phone" type="tel" autocomplete="tel" maxlength="40"></label><label>${tr('配送地区','배송 지역')}<select name="region"><option value="CN">${tr('中国','중국')}</option><option value="KR">${tr('韩国','한국')}</option><option value="OTHER">${tr('其他地区','기타')}</option></select></label><label>${tr('配送地址','배송 주소')}<textarea name="address" autocomplete="street-address" maxlength="500" required></textarea></label><label>${tr('备注（选填）','메모 (선택)')}<textarea name="notes" maxlength="500"></textarea></label><label class="check"><input name="consent" type="checkbox" required><span>${tr('同意使用上述信息处理本次申请，理解平台定价按已公布规则计算，最终价格、库存和运费需另行确认。','신청 처리를 위한 정보 사용에 동의합니다. 표시 가격은 판매자 규칙에 따른 가격이며 최종 금액·재고·배송비는 별도 확인합니다.')} <a href="#privacy" style="color:var(--red)">${tr('隐私说明','개인정보 안내')}</a></span></label><button class="primary" type="submit">${tr('提交购买申请','구매 신청 제출')} →</button><p class="consent-note">${tr('这是创业项目演示，请使用测试姓名和地址。申请不会产生付款或库存预留。','창업 프로젝트 데모입니다. 테스트 이름과 주소를 사용하세요. 신청은 결제나 재고 예약을 발생시키지 않습니다.')}</p><p id="submitError" class="error" role="alert"></p></form></section></div>`}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').showModal()}
function localReceipts(){return read('bridge-receipts',[])}
function ordersPage(){const receipts=localReceipts();$('#app').innerHTML=`<div class="banner-title"><span class="eyebrow">PURCHASE REQUESTS</span><h1>${tr('我的购买申请','나의 구매 신청')}</h1><p class="muted">${tr('在此浏览器提交的申请。点击更新可查看服务器状态，不代表支付订单。','이 브라우저에서 제출한 신청입니다. 상태를 새로 확인할 수 있으며 결제 주문이 아닙니다.')}</p></div>${receipts.length?receipts.map(o=>`<article class="order-card"><span class="order-status">${statusLabel(o.status)}</span><h3>${esc(o.id)}</h3><p class="muted">${esc(new Date(o.createdAt).toLocaleString(lang==='zh'?'zh-CN':'ko-KR'))} · ${money(o.total,o.currency)}</p><p>${o.items.map(i=>`${esc(name(products.find(p=>p.id===i.id))||i.id)} × ${i.quantity}`).join(' / ')}</p><button class="secondary" data-refresh-order="${esc(o.id)}">${tr('更新状态','상태 확인')}</button></article>`).join(''):`<div class="empty"><h2>${tr('还没有购买申请','아직 신청 내역이 없습니다')}</h2><a href="#shop" class="primary">${tr('前往商城','스토어로 이동')}</a></div>`}`}
function statusLabel(s){return ({pending:tr('待人工确认','확인 대기'),contacted:tr('已联系','연락 완료'),confirmed:tr('已确认','확인 완료'),closed:tr('已关闭','종료')})[s]||s}
function infoPage(which){const data={about:[tr('让热爱，不止于国界。','국경을 넘어 이어지는 즐거움.'),tr('LEGO Bridge 是一个面向中韩收藏者的创业项目，探索乐高收藏品展示、地区参考价格比较和跨境购买服务。','LEGO Bridge는 중국과 한국의 수집가를 위한 창업 프로젝트입니다. LEGO 컬렉션, 지역별 가격 비교, 해외 구매 서비스를 연결합니다.'),tr('我们相信，收藏不仅是拥有，更是发现、搭建与分享。第一版以精选套装和透明的价格信息为起点，通过人工确认，逐步完善商品检查与物流服务。','수집은 소유를 넘어 발견하고 조립하고 나누는 과정입니다. 추천 세트와 투명한 가격 정보를 시작으로, 개별 확인을 통해 검수와 배송 서비스를 발전시킵니다.')],contact:[tr('每一份收藏，都值得认真对待。','모든 컬렉션을 소중하게.'),tr('需要寻找特定套装，或咨询跨境配送？可以先提交购买申请并填写邮箱，我们将在后台查看。','특정 세트 또는 국제 배송에 대해 궁금하신가요? 구매 신청에 이메일을 남겨 주세요.'),tr('客服邮箱与聊天软件账号尚未配置。当前为项目演示，没有对外客服渠道或承诺响应时间。请使用测试信息提交申请。','고객센터 이메일과 채팅 계정은 아직 설정되지 않았습니다. 현재 데모이며 외부 상담 채널이나 응답 시간 보장은 없습니다. 테스트 정보로 신청해 주세요.')],privacy:[tr('隐私与演示说明','개인정보 및 데모 안내'),tr('购物车、收藏、语言选择和申请查询凭据保存在当前浏览器。姓名、邮箱、电话和地址通过申请接口保存到服务器的私有数据目录，不会写入公开 GitHub 仓库。申请数据仅供管理员处理本次联系与报价，当前演示请勿填写真实个人信息。','장바구니, 찜, 언어, 신청 조회 키는 현재 브라우저에 저장됩니다. 이름, 이메일, 전화번호, 주소는 서버의 비공개 데이터 폴더에 저장되며 공개 GitHub 저장소에 포함되지 않습니다. 신청 처리 및 연락에만 사용되며 데모에는 실제 개인정보를 입력하지 마세요.'),tr('商品资料和官方价格来自乐高官网，平台售价按商家规则计算，缺失价格标为待核实。没有实时汇率或投资承诺，库存需另行确认。商品图通过乐高官网外部图片地址展示，第三方会接收常规网络请求。正式运营前须配置运营者联系方式、数据保留和删除政策、真实商品资料及安全托管。','상품 정보와 공식 가격은 LEGO 공식 사이트에서 확인했으며 플랫폼 가격은 판매자 규칙으로 계산합니다. 미확인 가격은 비워 두며 재고는 별도 확인합니다. 실시간 환율이나 투자 약속은 없습니다. 사진은 LEGO 외부 주소로 표시되며 제3자에게 일반적인 웹 요청이 전달됩니다. 실제 운영 전 운영자 연락처, 보관·삭제 정책, 실제 상품 정보, 안전한 호스팅을 준비해야 합니다.')]};const [title,a,b]=data[which];$('#app').innerHTML=`<section class="intro panel"><span class="eyebrow">LEGO BRIDGE</span><h1>${title}</h1><p>${a}</p><p>${b}</p><a class="primary" href="#shop">${tr('探索商品','상품 둘러보기')} →</a>${which==='about'?benefits():''}</section>`}
function adminPage(){ $('#app').innerHTML=`<section class="panel intro"><span class="eyebrow">ADMINISTRATION</span><h1>${tr('申请管理','신청 관리')}</h1><p class="muted">${tr('输入服务器配置的管理员密钥查看申请。密钥不会保存在浏览器。未配置密钥时管理接口关闭。','서버 관리자 키로 신청을 확인하세요. 키는 브라우저에 저장하지 않으며 미설정 시 관리 기능이 닫힙니다.')}</p><form class="form" id="adminForm"><label>${tr('管理员密钥','관리자 키')}<input name="token" type="password" required autocomplete="off"></label><button class="primary">${tr('读取申请','신청 조회')}</button></form><div id="adminResults"></div></section>`}
let adminToken='';
function render(){adminToken='';chrome();const [page,id]=route().split('/');if(page==='home')home();else if(page==='shop')shop();else if(page==='product')detail(id);else if(page==='cart')cartPage();else if(page==='orders')ordersPage();else if(['about','contact','privacy'].includes(page))infoPage(page);else if(page==='admin')adminPage();else{$('#app').innerHTML=`<div class="empty">${tr('页面不存在','페이지를 찾을 수 없습니다')} <a href="#home">${tr('返回首页','홈')}</a></div>`}imageFallbacks();updateServiceStatus()}
function imageFallbacks(){document.querySelectorAll('img').forEach(i=>{i.onerror=()=>{i.alt=tr('商品图片暂不可用 · 产品编号见下方','상품 이미지 준비 중 · 제품 번호를 확인하세요');i.style.fontSize='10px';i.style.color='#aaa';i.style.padding='15px'}})}
function add(id,notify=true){const p=products.find(p=>p.id===id);if(!p||!canOrder(p)){toast(tr('当前地区报价或在售状态尚未确认','지역 가격 또는 판매 상태를 확인해 주세요'));return false}if((cart[id]||0)>=p.requestLimit){toast(tr('单次申请最多 10 件，更多数量请咨询','신청당 최대 10개입니다. 추가 수량은 문의하세요'));return false}cart[id]=(cart[id]||0)+1;persist();if(notify)toast(tr('已加入购物车','장바구니에 담았습니다'));return true}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.add&&add(b.dataset.add))cartFeedback(b);if(b.dataset.buy){if(!cart[b.dataset.buy]&&!add(b.dataset.buy,false))return;location.hash='cart'}if(b.dataset.favorite){e.preventDefault();const id=b.dataset.favorite;favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];localStorage.setItem('bridge-favorites',JSON.stringify(favorites));b.querySelector('.heart-icon').textContent=favorites.includes(id)?'♥':'♡';b.classList.toggle('selected',favorites.includes(id));b.setAttribute('aria-pressed',String(favorites.includes(id)));if(route()==='shop'&&filter==='favorites')shop()}if(b.dataset.category){visibleLimit=24;category=b.dataset.category;filter='all';if(route()==='shop')shop();else location.hash='shop';imageFallbacks()}if(b.dataset.filter){visibleLimit=24;filter=b.dataset.filter;shop();imageFallbacks()}if(b.dataset.homeFilter){document.querySelectorAll('[data-home-filter]').forEach(x=>x.classList.toggle('active',x===b));$('#homeGrid').innerHTML=products.filter(p=>p.confirmed&&(b.dataset.homeFilter==='stock'?canOrder(p):b.dataset.homeFilter==='affordable'?price(p)!=null&&price(p)<(lang==='zh'?1300:250000):true)).slice(0,8).map(card).join('');imageFallbacks()}if(b.id==='loadMore'){visibleLimit+=24;shop();imageFallbacks()}if(b.id==='resetFilters'){visibleLimit=24;query='';category='ALL';filter='all';sort='popular';shop();imageFallbacks()}if(b.dataset.remove){delete cart[b.dataset.remove];persist();cartPage();imageFallbacks()}if(b.dataset.quantity){const id=b.dataset.quantity;const q=cart[id]+Number(b.dataset.delta);if(q<1)delete cart[id];else if(q<=products.find(p=>p.id===id).requestLimit)cart[id]=q;persist();cartPage();imageFallbacks()}if(b.dataset.refreshOrder){const receipts=localReceipts(),o=receipts.find(x=>x.id===b.dataset.refreshOrder);try{b.disabled=true;const r=await fetch(`./api/orders/${encodeURIComponent(o.id)}`,{headers:{'X-Order-Key':o.key}});if(!r.ok)throw Error();const d=await r.json();o.status=d.status;localStorage.setItem('bridge-receipts',JSON.stringify(receipts));ordersPage();toast(tr('状态已更新','상태를 확인했습니다'))}catch{toast(tr('暂时无法查询，请确认服务器在线','서버 연결을 확인해 주세요'));b.disabled=false}}});
document.addEventListener('change',e=>{if(e.target.id==='seriesSelect'){category=e.target.value;visibleLimit=24;shop();imageFallbacks()}if(e.target.id==='sort'){visibleLimit=24;sort=e.target.value;shop();imageFallbacks()}if(e.target.dataset.orderStatus)updateStatus(e.target)});
document.addEventListener('submit',async e=>{if(e.target.id==='searchForm'){e.preventDefault();query=$('#searchInput').value.trim();visibleLimit=24;if(route()==='shop'){shop();imageFallbacks()}else location.hash='shop'}if(e.target.id==='orderForm'){e.preventDefault();const form=e.target,button=form.querySelector('button[type=submit]');button.disabled=true;$('#submitError').textContent='';try{const data=Object.fromEntries(new FormData(form));const items=Object.entries(cart).map(([id,quantity])=>({id,quantity}));const r=await fetch('./api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,items,currency:lang==='zh'?'CNY':'KRW',locale:lang})});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||tr('申请服务未连接，未提交任何信息。','신청 서버에 연결되지 않아 제출되지 않았습니다.'));const receipts=localReceipts();receipts.unshift({...d,items});localStorage.setItem('bridge-receipts',JSON.stringify(receipts));cart={};persist();location.hash='orders';modal(`<span class="eyebrow">REQUEST RECEIVED</span><h2>${tr('购买申请已收到','구매 신청이 접수되었습니다')}</h2><p>${esc(d.id)}</p><p class="muted">${tr('申请已保存到服务器，等待管理员确认。这不是付款订单，也没有预留库存。请保留当前浏览器中的查询凭据。','서버에 저장되었으며 관리자 확인을 기다립니다. 결제 주문이나 재고 예약이 아닙니다. 이 브라우저의 조회 키를 보관하세요.')}</p>`)}catch(err){$('#submitError').textContent=err.message;button.disabled=false}}if(e.target.id==='adminForm'){e.preventDefault();adminToken=new FormData(e.target).get('token');e.target.reset();await loadAdmin()}});
async function loadAdmin(){try{const r=await fetch('./api/admin/orders',{headers:{Authorization:`Bearer ${adminToken}`}});const d=await r.json();if(!r.ok)throw Error(tr('密钥不正确，或管理服务未开启。','키가 올바르지 않거나 관리 서비스가 꺼져 있습니다.'));$('#adminResults').innerHTML=`<p class="muted">${d.length} ${tr('条申请','건의 신청')}</p>`+d.map(o=>`<article class="admin-order"><b>${esc(o.id)}</b><p>${esc(o.customer)} · ${esc(o.email)} · ${esc(o.phone)}</p><p>${esc(o.region)} · ${esc(o.address)}</p><p>${o.items.map(i=>`#${esc(i.id)} × ${i.quantity}`).join(' / ')} · ${money(o.total,o.currency)}</p><p>${esc(o.notes)}</p><select data-order-status="${esc(o.id)}">${['pending','contacted','confirmed','closed'].map(s=>`<option value="${s}" ${o.status===s?'selected':''}>${statusLabel(s)}</option>`).join('')}</select><button class="text-button" data-delete-order="${esc(o.id)}">${tr('删除测试申请','테스트 신청 삭제')}</button></article>`).join('')}catch(e){$('#adminResults').textContent=e.message}}
async function updateStatus(select){try{select.disabled=true;const r=await fetch(`./api/admin/orders/${encodeURIComponent(select.dataset.orderStatus)}`,{method:'PATCH',headers:{Authorization:`Bearer ${adminToken}`,'Content-Type':'application/json'},body:JSON.stringify({status:select.value})});if(!r.ok)throw Error();toast(tr('状态已保存','상태가 저장되었습니다'))}catch{toast(tr('保存失败，请重新读取申请','저장 실패. 신청을 다시 조회하세요'));await loadAdmin()}finally{select.disabled=false}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-delete-order]');if(!b)return;modal(`<h2>${tr('删除这条测试申请？','테스트 신청을 삭제할까요?')}</h2><p class="muted">${tr('将从服务器永久移除申请中的联系与地址信息。','서버에서 신청과 연락처·주소를 영구 삭제합니다.')}</p><button class="primary" id="confirmDelete">${tr('确认删除','삭제 확인')}</button>`);$('#confirmDelete').onclick=async()=>{const r=await fetch(`./api/admin/orders/${encodeURIComponent(b.dataset.deleteOrder)}`,{method:'DELETE',headers:{Authorization:`Bearer ${adminToken}`}});$('#modal').close();toast(r.ok?tr('已删除','삭제 완료'):tr('删除失败','삭제 실패'));await loadAdmin()}});
$('#language').onclick=()=>{lang=lang==='zh'?'ko':'zh';localStorage.setItem('bridge-lang',lang);render()};$('#cartButton').onclick=()=>location.hash='cart';$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();

document.addEventListener('click',e=>{const b=e.target.closest('[data-gallery]');if(!b)return;const p=products.find(p=>p.id===b.dataset.productId);const i=Number(b.dataset.gallery);if(!p?.images[i])return;$('#galleryImage').src=imageUrl(p.images[i]);$('#galleryImage').alt=name(p)+' · '+(i===0?tr('主图','대표 이미지'):tr('细节图','디테일')+' '+i);document.querySelectorAll('[data-gallery]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});});
